    const bodyTxt = stripQuoteRef(mp.text, ev);
    const longTxt = !!bodyTxt && (bodyTxt.length > 480 || (bodyTxt.match(/\n/g)||[]).length > 10);
    const name = p.name||p.display_name||(npubOf(ev.pubkey).slice(0,12)+'…');
