      if(last && musicTracks(null).some(t=>t.sha===last.sha)){ this.play(last.sha,{force:true, at:last.pos||0}); return true; }
      const q=musicTracks(null);
      if(q.length){ this.play(q[0].sha,{force:true}); return true; }
